const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const global = ee.Geometry.Rectangle([-180, -90, 180, 90]);

  // 2. Data Acquisition - MODIS Land Cover
  const modis2003 = ee.ImageCollection('MODIS/006/MCD12Q1')
    .filterDate('2003-01-01', '2003-12-31')
    .first();

  const modis2019 = ee.ImageCollection('MODIS/006/MCD12Q1')
    .filterDate('2019-01-01', '2019-12-31')
    .first();

  // Check if images exist
  try {
    const has2003 = modis2003.getInfo();
    const has2019 = modis2019.getInfo();
  } catch (e) {
    print("No data for one or both years");
    print("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Extract cropland class (12)
  const crop2003 = modis2003.select('LC_Type1').eq(12);
  const crop2019 = modis2019.select('LC_Type1').eq(12);

  // Calculate pixel counts and area
  const stats2003 = crop2003.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: global,
    scale: 1000,
    maxPixels: 1e9
  });

  const stats2019 = crop2019.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: global,
    scale: 1000,
    maxPixels: 1e9
  });

  const pixels2003 = stats2003.get('LC_Type1').getInfo();
  const pixels2019 = stats2019.get('LC_Type1').getInfo();

  print(`2003 crop pixels: ${pixels2003}`);
  print(`2019 crop pixels: ${pixels2019}`);

  // Check for valid pixels
  if (pixels2003 === 0 || pixels2019 === 0) {
    print("No valid crop pixels detected");
    print("<answer>C2</answer>");
    return;
  }

  // 4. Calculation - Percentage change
  const percentChange = ((pixels2019 - pixels2003) / pixels2003 * 100);

  // 5. Validation & Final Answer
  print(`Percent change: ${percentChange.toFixed(2)}%`);

  if (isNaN(percentChange) || !isFinite(percentChange)) {
    print("<answer>C3</answer>");
  } else if (percentChange >= 5) {
    print("<answer>A</answer>");
  } else {
    print("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
